import React, { useState, useMemo } from 'react';
import { GitCompare, AlertTriangle, CheckCircle2, X, Info } from 'lucide-react';

/**
 * Akraba Evliliği (Inbreeding) Risk Hesaplayıcı Modalı
 * Seçilen damızlık erkek ile dişi hayvan arasındaki kan bağı katsayısını (Wright katsayısı) hesaplar.
 */
export default function InbreedingCalculatorModal({ isOpen, onClose, animals = [] }) {
  const [selectedFemaleId, setSelectedFemaleId] = useState('');
  const [selectedMaleId, setSelectedMaleId] = useState('');

  const females = useMemo(() => animals.filter(a => a.gender === 'F'), [animals]);
  const males = useMemo(() => animals.filter(a => a.gender === 'M'), [animals]);

  const female = useMemo(() => animals.find(a => String(a.id) === String(selectedFemaleId)), [animals, selectedFemaleId]);
  const male = useMemo(() => animals.find(a => String(a.id) === String(selectedMaleId)), [animals, selectedMaleId]);

  // Akrabalık hesabı simülasyonu (Wright's coefficient of relationship)
  const calculation = useMemo(() => {
    if (!female || !male) return null;

    let coeff = 0;
    let relationshipType = 'Akrabalık Bulunmuyor (Güvenli)';
    let level = 'safe'; // 'safe', 'moderate', 'danger', 'critical'
    let commonAncestors = [];

    // 1. Derece: Aynı ebeveynler (Kardeş)
    const sameMother = female.mother_id && female.mother_id === male.mother_id;
    const sameFather = female.father_id && female.father_id === male.father_id;

    // Ebeveyn - Yavru (Baba-Kız veya Anne-Oğul)
    const isFatherDaughter = male.id === female.father_id;
    const isMotherSon = female.id === male.mother_id;

    if (isFatherDaughter || isMotherSon) {
      coeff = 25.0;
      relationshipType = '1. Derece Ebeveyn - Yavru Çaprazlaması';
      level = 'critical';
    } else if (sameMother && sameFather) {
      coeff = 25.0;
      relationshipType = 'Tam Öz Kardeş';
      level = 'critical';
      commonAncestors.push('Ortak Anne & Ortak Baba');
    } else if (sameMother || sameFather) {
      coeff = 12.5;
      relationshipType = sameMother ? 'Üvey Kardeş (Ortak Anne)' : 'Üvey Kardeş (Ortak Baba)';
      level = 'danger';
      commonAncestors.push(sameMother ? 'Ortak Anne' : 'Ortak Baba');
    } else if (female.breed && male.breed && female.breed !== male.breed) {
      coeff = 0.0;
      relationshipType = 'Melezleme / Tamamen Bağımsız Hat (Heterozis Etkisi)';
      level = 'safe';
    } else {
      // Rastgele sürü içi arka plan riski
      coeff = 1.2;
      relationshipType = 'Uzak Sürü Akrabalığı';
      level = 'safe';
    }

    return { coeff, relationshipType, level, commonAncestors };
  }, [female, male]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-xs z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in">
        {/* Başlık */}
        <div className="p-5 border-b border-gray-100 flex items-center justify-between bg-teal-50/60">
          <div className="flex items-center gap-2.5">
            <div className="p-2 bg-teal-600 text-white rounded-xl">
              <GitCompare className="w-5 h-5" />
            </div>
            <div>
              <h3 className="font-bold text-gray-900 text-base">Akraba Evliliği Risk Hesaplayıcı</h3>
              <p className="text-xs text-teal-800">Damızlık eşleştirme öncesi genetik risk simülasyonu</p>
            </div>
          </div>
          <button onClick={onClose} className="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 hover:bg-white transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Seçim Alanı */}
        <div className="p-6 space-y-5">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-700 uppercase mb-1.5">
                ♀ Dişi Hayvan (Anaç)
              </label>
              <select
                value={selectedFemaleId}
                onChange={e => setSelectedFemaleId(e.target.value)}
                className="input-field text-xs"
              >
                <option value="">Dişi Seçin...</option>
                {females.map(f => (
                  <option key={f.id} value={f.id}>
                    {f.name} ({f.code}) - {f.breed || f.species}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-bold text-gray-700 uppercase mb-1.5">
                ♂ Erkek Hayvan (Boğa/Koç)
              </label>
              <select
                value={selectedMaleId}
                onChange={e => setSelectedMaleId(e.target.value)}
                className="input-field text-xs"
              >
                <option value="">Erkek Seçin...</option>
                {males.map(m => (
                  <option key={m.id} value={m.id}>
                    {m.name} ({m.code}) - {m.breed || m.species}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Sonuç Kartı */}
          {calculation ? (
            <div className={`p-4 rounded-2xl border transition-all ${
              calculation.level === 'critical'
                ? 'bg-rose-50 border-rose-200'
                : calculation.level === 'danger'
                ? 'bg-amber-50 border-amber-200'
                : 'bg-emerald-50 border-emerald-200'
            }`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-bold uppercase tracking-wider text-gray-600">
                  Genetik Akrabalık Katsayısı (F):
                </span>
                <span className={`text-xl font-black ${
                  calculation.level === 'critical' ? 'text-rose-600' :
                  calculation.level === 'danger' ? 'text-amber-600' : 'text-emerald-600'
                }`}>
                  %{calculation.coeff.toFixed(1)}
                </span>
              </div>

              <div className="flex items-start gap-2.5 mt-2">
                {calculation.level === 'critical' || calculation.level === 'danger' ? (
                  <AlertTriangle className="w-5 h-5 text-rose-600 flex-shrink-0 mt-0.5" />
                ) : (
                  <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0 mt-0.5" />
                )}
                <div>
                  <p className="text-sm font-bold text-gray-900 leading-tight">
                    {calculation.relationshipType}
                  </p>
                  <p className="text-xs text-gray-600 mt-1">
                    {calculation.level === 'critical'
                      ? '❌ KESİNLİKLE TAVSİYE EDİLMEZ! Yüksek embriyonik ölüm, anomalili yavru ve süt verimi düşüş riski çok yüksektir.'
                      : calculation.level === 'danger'
                      ? '⚠️ DİKKAT: Yarı kardeş çaprazlaması. Zorunlu olmadıkça farklı bir kan hattı erkek tercih ediniz.'
                      : '✅ GÜVENLİ EŞLEŞTİRME: Genetik çeşitlilik korunmakta olup yavru canlılığı ve verimi için idealdir.'}
                  </p>
                </div>
              </div>
            </div>
          ) : (
            <div className="p-8 text-center border-2 border-dashed border-gray-200 rounded-2xl text-gray-400">
              <Info className="w-6 h-6 mx-auto mb-2 text-gray-300" />
              <p className="text-xs font-medium">Lütfen analiz için dişi ve erkek hayvanı seçin</p>
            </div>
          )}
        </div>

        {/* Butonlar */}
        <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end">
          <button onClick={onClose} className="btn-secondary text-xs px-5 py-2">
            Kapat
          </button>
        </div>
      </div>
    </div>
  );
}
